registerScreenPlay("StarshipVendor", true)

StarshipVendor.mainMenu = nil

function StarshipVendor:getMainMenu()
	if (self.mainMenu ~= nil) then
		return self.mainMenu
	end

	local menu = {}
	local componentTypes = {}
	local directCategories = {}

	for i = 1, #self.categories, 1 do
		local category = self.categories[i]
		local levelStart, levelEnd = string.find(category.name, " %- Level ")

		if (levelStart ~= nil) then
			local componentType = string.sub(category.name, 1, levelStart - 1)
			local levelName = string.sub(category.name, levelEnd + 1)

			if (componentTypes[componentType] == nil) then
				componentTypes[componentType] = {}
			end

			table.insert(componentTypes[componentType], {
				name = levelName,
				categoryIndex = i
			})
		else
			table.insert(directCategories, {
				name = category.name,
				categoryIndex = i
			})
		end
	end

	for i = 1, #directCategories, 1 do
		table.insert(menu, {
			name = directCategories[i].name,
			categoryIndex = directCategories[i].categoryIndex,
			isComponentType = false
		})
	end

	local typeNames = {}

	for typeName, _ in pairs(componentTypes) do
		table.insert(typeNames, typeName)
	end

	table.sort(typeNames)

	for i = 1, #typeNames, 1 do
		local typeName = typeNames[i]

		table.sort(componentTypes[typeName], function(a, b)
			local aLevel = tonumber(string.match(a.name, "%d+")) or 0
			local bLevel = tonumber(string.match(b.name, "%d+")) or 0
			return aLevel < bLevel
		end)

		table.insert(menu, {
			name = typeName,
			levels = componentTypes[typeName],
			isComponentType = true
		})
	end

	self.mainMenu = menu
	return self.mainMenu
end


function StarshipVendor:start()
end

function StarshipVendor:openCategoryMenu(pPlayer, pNpc)
	if (pPlayer == nil) then
		return
	end

	local menu = self:getMainMenu()

	local sui = SuiListBox.new("StarshipVendor", "handleCategorySelection")
	sui.setTargetNetworkId(SceneObject(pNpc):getObjectID())
	sui.setTitle("Starship Dealer")
	sui.setPrompt("Choose a Jump to Lightspeed category.")

	for i = 1, #menu, 1 do
		sui.add(menu[i].name, tostring(i - 1))
	end

	sui.sendTo(pPlayer)
end

function StarshipVendor:handleCategorySelection(pPlayer, pSui, eventIndex, args)
	if (pPlayer == nil or args == nil or args == "") then
		return
	end

	local selectedIndex = tonumber(args)

	if (selectedIndex == nil) then
		CreatureObject(pPlayer):sendSystemMessage("Invalid ship category selection.")
		return
	end

	local menuIndex = selectedIndex + 1
	local menu = self:getMainMenu()
	local entry = menu[menuIndex]

	if (entry == nil) then
		CreatureObject(pPlayer):sendSystemMessage("Invalid ship category.")
		return
	end

	if (entry.isComponentType) then
		self:openLevelMenu(pPlayer, menuIndex)
	else
		self:openItemGroupMenu(pPlayer, entry.categoryIndex)
	end
end

function StarshipVendor:openLevelMenu(pPlayer, menuIndex)
	if (pPlayer == nil or menuIndex == nil) then
		return
	end

	local menu = self:getMainMenu()
	local entry = menu[menuIndex]

	if (entry == nil or entry.levels == nil) then
		CreatureObject(pPlayer):sendSystemMessage("Invalid component category.")
		return
	end

	-- Store the selected component type, not a category index.
	writeData(SceneObject(pPlayer):getObjectID() .. ":starshipVendorMenuIndex", menuIndex)

	local sui = SuiListBox.new("StarshipVendor", "handleLevelSelection")
	sui.setTitle(entry.name)
	sui.setPrompt("Choose a component level.")

	for i = 1, #entry.levels, 1 do
		-- Store the row within this component type.
		sui.add(entry.levels[i].name, tostring(i - 1))
	end

	sui.sendTo(pPlayer)
end

function StarshipVendor:handleLevelSelection(pPlayer, pSui, eventIndex, args)
	if (pPlayer == nil or args == nil or args == "") then
		return
	end

	local menuIndex = readData(SceneObject(pPlayer):getObjectID() .. ":starshipVendorMenuIndex")
	deleteData(SceneObject(pPlayer):getObjectID() .. ":starshipVendorMenuIndex")

	if (menuIndex == nil or menuIndex == 0) then
		CreatureObject(pPlayer):sendSystemMessage("Invalid component category.")
		return
	end

	local menu = self:getMainMenu()
	local entry = menu[menuIndex]

	if (entry == nil or entry.levels == nil) then
		CreatureObject(pPlayer):sendSystemMessage("Invalid component category.")
		return
	end

	local selectedIndex = tonumber(args)

	if (selectedIndex == nil) then
		CreatureObject(pPlayer):sendSystemMessage("Invalid component level selection.")
		return
	end

	local levelIndex = selectedIndex + 1

	if (entry.levels[levelIndex] == nil) then
		CreatureObject(pPlayer):sendSystemMessage("Invalid component level.")
		return
	end

	self:openItemGroupMenu(pPlayer, entry.levels[levelIndex].categoryIndex)
end

function StarshipVendor:openItemGroupMenu(pPlayer, categoryIndex)
	if (pPlayer == nil or categoryIndex == nil) then
		return
	end

	local category = self.categories[categoryIndex]

	if (category == nil) then
		CreatureObject(pPlayer):sendSystemMessage("Invalid ship category.")
		return
	end

	local itemCount = #category.items

	if (itemCount < 1) then
		CreatureObject(pPlayer):sendSystemMessage("No items found in this category.")
		return
	end

	local pageSize = 20

	if (itemCount <= pageSize) then
		self:openItemMenu(pPlayer, categoryIndex, 1, itemCount)
		return
	end

	writeData(SceneObject(pPlayer):getObjectID() .. ":starshipVendorCategory", categoryIndex)

	local sui = SuiListBox.new("StarshipVendor", "handleItemGroupSelection")
	sui.setTitle(category.name)
	sui.setPrompt("Choose an item group.")

	local startIndex = 1

	while (startIndex <= itemCount) do
		local endIndex = startIndex + pageSize - 1

		if (endIndex > itemCount) then
			endIndex = itemCount
		end

		sui.add("Items " .. startIndex .. "-" .. endIndex, tostring(startIndex - 1))

		startIndex = endIndex + 1
	end

	sui.sendTo(pPlayer)
end

function StarshipVendor:handleItemGroupSelection(pPlayer, pSui, eventIndex, args)
	if (pPlayer == nil or args == nil or args == "") then
		return
	end

	local categoryIndex = readData(SceneObject(pPlayer):getObjectID() .. ":starshipVendorCategory")

	if (categoryIndex == nil or categoryIndex == 0 or self.categories[categoryIndex] == nil) then
		CreatureObject(pPlayer):sendSystemMessage("Invalid ship category.")
		return
	end

	local selectedStart = tonumber(args)

	if (selectedStart == nil) then
		CreatureObject(pPlayer):sendSystemMessage("Invalid item group selection.")
		return
	end

	local startIndex = selectedStart + 1
	local endIndex = startIndex + 19

	if (endIndex > #self.categories[categoryIndex].items) then
		endIndex = #self.categories[categoryIndex].items
	end

	self:openItemMenu(pPlayer, categoryIndex, startIndex, endIndex)
end

function StarshipVendor:openItemMenu(pPlayer, categoryIndex, startIndex, endIndex)
	if (pPlayer == nil) then
		return
	end

	local category = self.categories[categoryIndex]

	if (category == nil) then
		CreatureObject(pPlayer):sendSystemMessage("Invalid ship category.")
		return
	end

	if (startIndex == nil) then
		startIndex = 1
	end

	if (endIndex == nil or endIndex > #category.items) then
		endIndex = #category.items
	end

	writeData(SceneObject(pPlayer):getObjectID() .. ":starshipVendorCategory", categoryIndex)

	local sui = SuiListBox.new("StarshipVendor", "handleItemSelection")
	sui.setTitle(category.name)
	sui.setPrompt("Select an item to buy. Prices are shown beside each item.")

	for i = startIndex, endIndex, 1 do
		local item = category.items[i]
		sui.add(item.name .. " - " .. item.price .. " credits", tostring(i - 1))
	end

	sui.sendTo(pPlayer)
end

function StarshipVendor:handleItemSelection(pPlayer, pSui, eventIndex, args)
	if (pPlayer == nil or args == nil or args == "") then
		return
	end

	local categoryIndex = readData(SceneObject(pPlayer):getObjectID() .. ":starshipVendorCategory")
	deleteData(SceneObject(pPlayer):getObjectID() .. ":starshipVendorCategory")

	if (categoryIndex == nil or categoryIndex == 0 or self.categories[categoryIndex] == nil) then
		CreatureObject(pPlayer):sendSystemMessage("Invalid ship category.")
		return
	end

	local selectedIndex = tonumber(args)

	if (selectedIndex == nil) then
		CreatureObject(pPlayer):sendSystemMessage("Invalid ship item selection.")
		return
	end

	local itemIndex = selectedIndex + 1
	local category = self.categories[categoryIndex]

	if (category.items[itemIndex] == nil) then
		CreatureObject(pPlayer):sendSystemMessage("Invalid ship item.")
		return
	end

	self:buyItem(pPlayer, category.items[itemIndex])
end

function StarshipVendor:buyItem(pPlayer, item)
	if (pPlayer == nil or item == nil) then
		return
	end

	local pInventory = SceneObject(pPlayer):getSlottedObject("inventory")

	if (pInventory == nil) then
		CreatureObject(pPlayer):sendSystemMessage("Unable to locate your inventory.")
		return
	end

	if (SceneObject(pInventory):isContainerFullRecursive()) then
		CreatureObject(pPlayer):sendSystemMessage("Your inventory is full.")
		return
	end

	local price = item.price or 0

	if (CreatureObject(pPlayer):getCashCredits() < price) then
		CreatureObject(pPlayer):sendSystemMessage("You need " .. price .. " credits to buy this item.")
		return
	end

	local pItem = giveItem(pInventory, item.template, -1, true)

	if (pItem == nil) then
		CreatureObject(pPlayer):sendSystemMessage("Unable to create item: " .. item.template)
		return
	end

	CreatureObject(pPlayer):subtractCashCredits(price)
	CreatureObject(pPlayer):sendSystemMessage("Purchased: " .. item.name .. " for " .. price .. " credits.")
end
